uint4 transform(uint4 x) {
    uint2 low = x.yx;
    uint3 triple = uint3(low, x.z);
    uint4 word = uint4(triple, x.w);
    word.xy = word.yx;
    word += 1u;
    word -= uint4(2u, 3u, 4u, 5u);
    word *= 7u;
    word &= 0x7fffffffu;
    word |= uint4(1u, 2u, 4u, 8u);
    word ^= x;
    word <<= uint4(0u, 31u, 32u, 63u);
    word >>= 1u;
    return ~word;
}
float4 main(float4 input : COLOR0) : SV_Target {
    return asfloat(transform(asuint(input)));
}

float4 main(float4 input : COLOR0) : SV_Target {
    uint4 words = asuint(input);
    uint values[4] = {words.x, words.y, words.z, words.w};
    uint result[4];
    [unroll] for (uint i = 0u; i < 4u; ++i) {
        result[i] = values[i] ^ (1u << (i + 32u));
    }
    return asfloat(uint4(result[0], result[1], result[2], result[3]));
}
